def main():
    ap = argparse.ArgumentParser(description="Résidence Azur Méditerranée - site web en un fichier")
    ap.add_argument("--port", type=int, default=8000)
    ap.add_argument("--lan", action="store_true", help="accessible depuis le téléphone / autre PC du réseau")
    ap.add_argument("--no-browser", action="store_true")
    a = ap.parse_args()

    if not os.path.isdir(IMAGES_DIR):
        print("\n  [!] Dossier introuvable : %s" % IMAGES_DIR)
        print("      Créez un dossier 'images' à côté de ce fichier et mettez-y vos photos.\n")
    else:
        missing = [n for n in EXPECTED if not find_image(n)]
        n_ok = len(EXPECTED) - len(missing)
        print("  Photos liées : %d / %d" % (n_ok, len(EXPECTED)))
        for m in missing:
            print("    [manquante] images/%s" % m)

    host = "0.0.0.0" if a.lan else "127.0.0.1"
    try:
        srv = ThreadingHTTPServer((host, a.port), Handler)
    except OSError:
        print("  Port %d occupé, essayez : python %s --port %d" % (a.port, os.path.basename(__file__), a.port + 1))
        sys.exit(1)
    srv.daemon_threads = True
    url = "http://localhost:%d" % a.port
    print("\n  Résidence Azur Méditerranée en ligne :  %s" % url)
    if a.lan:
        print("  Sur le réseau local              :  http://%s:%d" % (lan_ip(), a.port))
    print("  (Ctrl+C pour arrêter)\n")
    if not a.no_browser:
        threading.Timer(0.8, lambda: webbrowser.open(url)).start()
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        print("\n  Arrêt.")
        srv.server_close()


if __name__ == "__main__":
    main()
